def solve(tokens):
    """Evaluate an expression given in Reverse Polish Notation.
    Tokens are strings representing integers or the operators +, -, *, /.
    Division should truncate toward zero, matching the typical LeetCode RPN problem.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division, truncate toward zero
                # Using int(a / b) achieves truncation toward zero for both signs
                res = int(a / b)
            stack.append(res)
        else:
            # token is an integer literal
            stack.append(int(tok))
    return stack[0] if stack else 0
}

