def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting (binary search) for O(n log n).
    """
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest ending value of an IS of length i+1
    for x in nums:
        # find insertion point (first >= x) for strictly increasing, we need >
        # So use bisect_left on tails with x to replace first >= x
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

