def solve(grid):
    """Count the number of islands (connected components of 1s) in a 2D grid.
    Connectivity is 4-directional (up, down, left, right).
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # neighbors
            if x > 0 and grid[x-1][y] == 1 and not visited[x-1][y]:
                stack.append((x-1, y))
            if x + 1 < rows and grid[x+1][y] == 1 and not visited[x+1][y]:
                stack.append((x+1, y))
            if y > 0 and grid[x][y-1] == 1 and not visited[x][y-1]:
                stack.append((x, y-1))
            if y + 1 < cols and grid[x][y+1] == 1 and not visited[x][y+1]:
                stack.append((x, y+1))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

