def solve(s: str) -> bool:
    """Check if brackets in s are balanced.
    Considers (), [], {}. Ignores other characters.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack
}

