def solve(grid):
    if not grid:
        return 0
    cells = [list(row) for row in grid]
    rows = len(cells)
    cols = len(cells[0]) if rows else 0
    count = 0
    for r in range(rows):
        for c in range(cols):
            if cells[r][c] == 1:
                count += 1
                stack = [(r, c)]
                cells[r][c] = 0
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and cells[nr][nc] == 1:
                            cells[nr][nc] = 0
                            stack.append((nr, nc))
    return count

